    public MainMenuScreen()
      : base("Main Menu", (Player) null)
    {
      List<BlockMenuEntry> blockMenuEntryList1 = new List<BlockMenuEntry>();
      blockMenuEntryList1.Add(new BlockMenuEntry((BlockMenuScreen) this, "Play"));
      blockMenuEntryList1.Add(new BlockMenuEntry((BlockMenuScreen) this, "Photos"));
      blockMenuEntryList1.Add(new BlockMenuEntry((BlockMenuScreen) this, "Setup"));
      blockMenuEntryList1.Add(new BlockMenuEntry((BlockMenuScreen) this, "Credits"));
      blockMenuEntryList1.Add(new BlockMenuEntry((BlockMenuScreen) this, "Update Notes"));
      blockMenuEntryList1.Add(new BlockMenuEntry((BlockMenuScreen) this, "Exit"));
      int num1 = 0;
      List<BlockMenuEntry> blockMenuEntryList2 = blockMenuEntryList1;
      int index1 = num1;
      int num2 = index1 + 1;
      blockMenuEntryList2[index1].Selected += new EventHandler<PlayerIndexEventArgs>(this.PlayGameMenuEntrySelected);
      List<BlockMenuEntry> blockMenuEntryList3 = blockMenuEntryList1;
      int index2 = num2;
      int num3 = index2 + 1;
      blockMenuEntryList3[index2].Selected += new EventHandler<PlayerIndexEventArgs>(this.PhotosMenuEntrySelected);
      List<BlockMenuEntry> blockMenuEntryList4 = blockMenuEntryList1;
      int index3 = num3;
      int num4 = index3 + 1;
      blockMenuEntryList4[index3].Selected += new EventHandler<PlayerIndexEventArgs>(this.SetupMenuEntrySelected);
      List<BlockMenuEntry> blockMenuEntryList5 = blockMenuEntryList1;
      int index4 = num4;
      int num5 = index4 + 1;
      blockMenuEntryList5[index4].Selected += new EventHandler<PlayerIndexEventArgs>(this.CreditsMenuEntrySelected);
      List<BlockMenuEntry> blockMenuEntryList6 = blockMenuEntryList1;
      int index5 = num5;
      int num6 = index5 + 1;
      blockMenuEntryList6[index5].Selected += new EventHandler<PlayerIndexEventArgs>(this.UpdateMenuEntrySelected);
      List<BlockMenuEntry> blockMenuEntryList7 = blockMenuEntryList1;
      int index6 = num6;
      int num7 = index6 + 1;
      blockMenuEntryList7[index6].Selected += new EventHandler<PlayerIndexEventArgs>(((MenuScreen) this).OnCancel);
      this.MenuEntries.AddRange((IEnumerable<MenuEntry>) blockMenuEntryList1.ToArray());
    }

    public override void LoadContent()
    {
      this.DrawLeftMarginLine = this.DrawPanel = false;
      this.DrawItemTextures = this.DrawLastLine = false;
      this.DrawTitleStrip = false;
      this.HighlightRect.Width = 280;
      this.ItemHeight = 40;
      this.ItemGapY = 4;
      this.ItemTextScale = 0.7f;
      this.Font = CoreGlobals.GameFont;
      this.ItemFont = CoreGlobals.GameFont;
      base.LoadContent();
      this.kk = Directory.GetFiles(".", "*.exe").Length > 1;
    }

    protected override void OnScreenAddedCore()
    {
      base.OnScreenAddedCore();
      if (Globals2.AutoStartMap != 0)
        this.PlayGameMenuEntrySelected((object) null, new PlayerIndexEventArgs(this.ControllingPlayer.Value));
      if (!this.kk)
        return;
      this.ScreenManager.AddScreen((GameScreen) new MessageBoxScreenTM("Unauthorized files found.\n\nRemove the unauthorized files and relaunch the game.", "Ok", (string) null, (string) null, (string) null, CoreGlobals.GameFont, 1f, new MessageBoxScreen.DrawMessageBoxBackgroundHandler(GraphicStatics.DrawMessageBoxBackground), Globals2.GetSignedInGamer(this.ControllingPlayer).Tag as Player), this.ControllingPlayer);
      this.ExitScreen();
    }

    private void PlayGameMenuEntrySelected(object sender, PlayerIndexEventArgs e)
    {
      ModManager.UnloadAllActiveMods();
      Globals2.GameProperties = new GameProperties(MapType.Map);
      Globals2.GameProperties.SaveGame.Header.SaveVersion = 294;
      Globals2.GameProperties.SaveGame.Header.MaxPlayers = 16;
      this.ScreenManager.AddScreen((GameScreen) new NewSessionTypeMenuScreen((Action) null), new PlayerIndex?(e.PlayerIndex));
    }

    private void PhotosMenuEntrySelected(object sender, PlayerIndexEventArgs e)
    {
      if (this.IsNotSignedIn())
        return;
      if (Globals2.GetPhotoCount() == 0)
        this.ScreenManager.AddScreen((GameScreen) new MessageBoxScreenTM("You do not have any photos", "Ok", (string) null, (string) null, (string) null, CoreGlobals.GameFont, 0.8f, new MessageBoxScreen.DrawMessageBoxBackgroundHandler(GraphicStatics.DrawMessageBoxBackground), this.player), this.ControllingPlayer);
      else
        this.ScreenManager.AddScreen((GameScreen) new PhotoAlbumScreen(), new PlayerIndex?(e.PlayerIndex));
    }

    private void SkillsMenuEntrySelected(object sender, PlayerIndexEventArgs e)
    {
      if (this.IsNotSignedIn())
        return;
      Gamer signedInGamer = Globals2.GetSignedInGamer(this.ControllingPlayer.Value);
      if (signedInGamer == null)
        return;
      this.ScreenManager.AddScreen((GameScreen) new SkillsScreen(Globals2.GamertagData.GetPlayerSkillData(signedInGamer), signedInGamer.Gamertag), this.ControllingPlayer);
    }

    private void SetupMenuEntrySelected(object sender, PlayerIndexEventArgs e)
    {
      if (this.IsNotSignedIn())
        return;
      this.ScreenManager.AddScreen((GameScreen) new GlobalOptionsSetupScreen(this.ControllingPlayer.Value), this.ControllingPlayer);
    }

    private void CreditsMenuEntrySelected(object sender, PlayerIndexEventArgs e)
    {
      this.ScreenManager.AddScreen((GameScreen) new CreditsScreen(), new PlayerIndex?(e.PlayerIndex));
    }

    private void UpdateMenuEntrySelected(object sender, PlayerIndexEventArgs e)
    {
      this.ScreenManager.AddScreen((GameScreen) new HowToScreen((Player) null, "Update Information: v2.7", this.updateNotes, 0.6f), new PlayerIndex?(e.PlayerIndex));
    }

    public override void OnCancel(PlayerIndex playerIndex)
    {
      MessageBoxScreen messageBoxScreen = (MessageBoxScreen) new MessageBoxScreenTM("Are you sure you want to exit the game?", "Yes please, I want to exit", (string) null, (string) null, "No, I'll continue playing", this.Font, 0.8f, new MessageBoxScreen.DrawMessageBoxBackgroundHandler(GraphicStatics.DrawMessageBoxBackground), this.player);
      messageBoxScreen.ButtonA += new EventHandler<PlayerIndexEventArgs>(this.ConfirmExitMessageBoxAccepted);
      this.ScreenManager.AddScreen((GameScreen) messageBoxScreen, new PlayerIndex?(playerIndex));
    }

    private void ConfirmExitMessageBoxAccepted(object sender, PlayerIndexEventArgs e)
    {
      this.ScreenManager.Game.Exit();
    }

    private bool IsNotSignedIn()
    {
      if (Globals2.GetSignedInGamer(this.ControllingPlayer) != null)
        return false;
      this.ScreenManager.AddScreen((GameScreen) new MessageBoxScreen("You must sign in", "Ok", (string) null, (string) null, (string) null, this.Font, 0.8f, new MessageBoxScreen.DrawMessageBoxBackgroundHandler(GraphicStatics.DrawMessageBoxBackground)), this.ControllingPlayer);
      return true;
    }

    protected override void DrawTitle()
    {
    }

    protected override void DrawButtons(int x)
    {
    }
  }
